def get_book_by_title(title, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        ss = s.strip()
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _norm_title(t):
        t = t.strip()
        t = " ".join(t.split())
        return t.lower()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, api_key_id, status, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta or {}
        })
        _save("request_logs.json", logs)

    def _reset_daily_if_needed(krow, now_dt):
        ws = _parse_dt(krow.get("daily_window_started_at"))
        if ws is None:
            krow["daily_window_started_at"] = _iso(now_dt)
            krow["daily_used_requests"] = 0
            return
        if (now_dt - ws) >= datetime.timedelta(hours=24):
            krow["daily_window_started_at"] = _iso(now_dt)
            krow["daily_used_requests"] = 0

    t0 = time.time()
    endpoint = "get_book_by_title"

    # Validate input
    if not isinstance(title, str):
        _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title must be a string")
    title_trim = title.strip()
    if not title_trim:
        _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title must be non-empty after trimming")

    now_dt = _now()

    # Ambient authentication: pick an API key that can serve the call (active + quota available)
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    chosen_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        # validate counters
        if not isinstance(k.get("daily_limit_requests"), int) or k.get("daily_limit_requests") < 0:
            continue
        if not isinstance(k.get("daily_used_requests"), int) or k.get("daily_used_requests") < 0:
            continue
        k_tmp = dict(k)
        _reset_daily_if_needed(k_tmp, now_dt)
        if k_tmp["daily_used_requests"] + 1 <= k_tmp["daily_limit_requests"]:
            chosen_key = k
            break

    if chosen_key is None:
        _log(endpoint, None, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "No active API key with available quota could be resolved for this call")

    api_key_id = chosen_key.get("id")

    # Enforce quota (rolling day window)
    _reset_daily_if_needed(chosen_key, now_dt)
    if chosen_key["daily_used_requests"] + 1 > chosen_key["daily_limit_requests"]:
        _log(endpoint, api_key_id, "error", (time.time() - t0) * 1000, {"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for this API key")

    # Find a cached succeeded query for this title that hasn't expired
    title_norm = _norm_title(title_trim)
    queries = _load("title_search_queries.json")
    if not isinstance(queries, list):
        queries = []

    cached_q = None
    for q in queries:
        if not isinstance(q, dict):
            continue
        if q.get("title_normalized") != title_norm:
            continue
        if q.get("status") != "succeeded":
            continue
        ce = _parse_dt(q.get("cache_expires_at"))
        if ce is not None and ce > now_dt:
            cached_q = q
            break

    # Always create a new query record for this call (business rule)
    new_q = {
        "id": _gen_id("olmk_qry"),
        "api_key_id": api_key_id,
        "title_raw": title_trim,
        "title_normalized": title_norm,
        "status": "queued",
        "requested_limit": 20,
        "upstream_url": None,
        "upstream_http_status": None,
        "upstream_etag": None,
        "upstream_last_modified": None,
        "error_code": None,
        "error_message": None,
        "fetched_at": None,
        "cache_expires_at": None,
        "created_at": _iso(now_dt),
        "updated_at": _iso(now_dt),
    }
    queries.append(new_q)

    # If cache hit, return cached results without upstream; mark the created query as succeeded and link its cache metadata
    results_rows = []
    works_by_id = {}
    authors_by_id = {}
    if cached_q is not None:
        # Transition queued -> fetching -> succeeded (legal)
        new_q["status"] = "fetching"
        new_q["updated_at"] = _iso(now_dt)
        new_q["status"] = "succeeded"
        new_q["updated_at"] = _iso(now_dt)
        # carry forward upstream/cache metadata
        for f in ["upstream_url", "upstream_http_status", "upstream_etag", "upstream_last_modified", "fetched_at", "cache_expires_at"]:
            new_q[f] = cached_q.get(f)

        all_results = _load("title_query_results.json")
        if not isinstance(all_results, list):
            all_results = []
        # filter for cached query id (not new_q id)
        cached_results = [r for r in all_results if isinstance(r, dict) and r.get("query_id") == cached_q.get("id")]
        cached_results.sort(key=lambda r: r.get("rank") if isinstance(r.get("rank"), int) else 10**9)
        results_rows = cached_results

        works = _load("ol_works.json")
        if not isinstance(works, list):
            works = []
        authors = _load("ol_authors.json")
        if not isinstance(authors, list):
            authors = []
        works_by_id = {w.get("id"): w for w in works if isinstance(w, dict) and w.get("id")}
        authors_by_id = {a.get("id"): a for a in authors if isinstance(a, dict) and a.get("id")}

    else:
        # Cache miss: we cannot call upstream offline. Persist query as failed via valid transitions.
        new_q["status"] = "fetching"
        new_q["updated_at"] = _iso(now_dt)
        new_q["status"] = "failed"
        new_q["updated_at"] = _iso(now_dt)
        new_q["error_code"] = "UPSTREAM_UNAVAILABLE"
        new_q["error_message"] = "Upstream fetch not available in offline datastore mode"
        # Do NOT return CONFLICT; return a normal failed query response (realistic behavior) while still persisting.
        _save("title_search_queries.json", queries)

        # Count this as a successful tool call? Business rule says successful tool call increments.
        # This call returned a valid response but indicates failure; treat as not successful for quota count.
        _log(endpoint, api_key_id, "ok", (time.time() - t0) * 1000, {"cache": "miss", "status": "failed"})
        return {
            "query": new_q,
            "from_cache": False,
            "results": [],
            "works": [],
            "authors": [],
            "meta": {"total_results": 0}
        }

    # Persist query creation + possible status updates
    _save("title_search_queries.json", queries)

    # Increment quota usage only for successful tool call (this one returned data)
    chosen_key["daily_used_requests"] = int(chosen_key.get("daily_used_requests", 0)) + 1
    chosen_key["last_used_at"] = _iso(now_dt)
    chosen_key["updated_at"] = _iso(now_dt)
    _save("api_keys.json", api_keys)

    # Build normalized response
    out_results = []
    out_works = []
    out_authors = []
    seen_work_ids = set()
    seen_author_ids = set()

    for r in results_rows:
        if not isinstance(r, dict):
            continue
        wid = r.get("work_id")
        if wid and wid in works_by_id and wid not in seen_work_ids:
            out_works.append(works_by_id[wid])
            seen_work_ids.add(wid)
        a_ids = r.get("author_ids") if isinstance(r.get("author_ids"), list) else []
        for aid in a_ids:
            if aid in authors_by_id and aid not in seen_author_ids:
                out_authors.append(authors_by_id[aid])
                seen_author_ids.add(aid)
        out_results.append(r)

    _log(endpoint, api_key_id, "ok", (time.time() - t0) * 1000, {"cache": "hit", "cached_query_id": cached_q.get("id") if cached_q else None})
    return {
        "query": new_q,
        "from_cache": True,
        "results": out_results,
        "works": out_works,
        "authors": out_authors,
        "meta": {"total_results": len(out_results)}
    }

def list_title_search_queries(api_key, status=None, title_normalized=None, title_contains=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _log(endpoint, api_key_id, status_s, latency_ms, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": "req_" + str(int(time.time() * 1000)) + "_" + str(os.getpid()),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    # Validate
    if not isinstance(api_key, str) or not api_key:
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if status is not None:
        if status not in ["queued", "fetching", "succeeded", "failed"]:
            _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid status filter")
    if title_normalized is not None and not isinstance(title_normalized, str):
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title_normalized must be a string")
    if title_contains is not None and not isinstance(title_contains, str):
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title_contains must be a string")
    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "limit must be between 1 and 100")

    ca = _parse_dt(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time")
    cb = _parse_dt(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time")

    # Authenticate api_key by id (since only key_hash exists; never compare to hash)
    api_keys = _load("api_keys.json")
    krow = None
    for k in api_keys:
        if k.get("id") == api_key:
            krow = k
            break
    if krow is None:
        _log("list_title_search_queries", None, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")

    if krow.get("status") != "active":
        _log("list_title_search_queries", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is not active")

    now = _now()
    # quota window reset
    win = _parse_dt(krow.get("daily_window_started_at"))
    if win is None or (now - win >= datetime.timedelta(hours=24)):
        krow["daily_used_requests"] = 0
        krow["daily_window_started_at"] = _iso(now)
    used = krow.get("daily_used_requests")
    lim = krow.get("daily_limit_requests")
    if not isinstance(used, int) or not isinstance(lim, int) or lim < 0 or used < 0:
        _log("list_title_search_queries", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "API key quota fields invalid")
    if used + 1 > lim:
        _log("list_title_search_queries", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    # Decode cursor
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str):
            _log("list_title_search_queries", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "cursor must be a string")
        try:
            raw = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"==").decode("utf-8")
            if not raw.startswith("offset:"):
                raise ValueError("bad cursor")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                offset = 0
        except Exception:
            _log("list_title_search_queries", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
            return _err("VALIDATION_ERROR", "Invalid cursor")

    queries = _load("title_search_queries.json")
    # visible to calling key: api_key_id match
    rows = [q for q in queries if q.get("api_key_id") == krow.get("id")]

    if status is not None:
        rows = [q for q in rows if q.get("status") == status]
    if title_normalized is not None:
        rows = [q for q in rows if q.get("title_normalized") == title_normalized]
    if title_contains is not None:
        needle = " ".join(title_contains.strip().split()).lower()
        def _raw_match(q):
            tr = q.get("title_raw")
            if not isinstance(tr, str):
                return False
            hay = " ".join(tr.strip().split()).lower()
            return needle in hay
        rows = [q for q in rows if _raw_match(q)]
    if ca is not None:
        rows = [q for q in rows if (_parse_dt(q.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) >= ca]
    if cb is not None:
        rows = [q for q in rows if (_parse_dt(q.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)) < cb]

    # order by updated_at desc (fallback created_at)
    def _upd(q):
        return _parse_dt(q.get("updated_at")) or _parse_dt(q.get("created_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)
    rows.sort(key=_upd, reverse=True)

    total = len(rows)
    page = rows[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"offset:{next_off}".encode("utf-8")).decode("utf-8").rstrip("=")

    # increment successful call
    krow["daily_used_requests"] = used + 1
    krow["last_used_at"] = _iso(now)
    krow["updated_at"] = _iso(now)
    for i, kk in enumerate(api_keys):
        if kk.get("id") == krow.get("id"):
            api_keys[i] = krow
            break
    _save("api_keys.json", api_keys)

    resp = {
        "data": page,
        "pagination": {"total": total, "limit": limit, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
    }
    _log("list_title_search_queries", krow.get("id"), "ok", (time.time() - t0) * 1000, {"returned": len(page)})
    return resp

def get_title_search_query(api_key, id, include_results=None, results_limit=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_dt_lenient(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _log(endpoint, api_key_id, status_s, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _iso(_now())
        logs.append({
            "id": f"olmk_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": ts,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _normalize_title(s):
        s = s.strip()
        parts = s.split()
        return " ".join(parts).lower()

    def _resolve_api_key(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        # Authenticate by client-visible id OR by presenting stored key_hash literally (cannot verify plaintext).
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == v or k.get("key_hash") == v:
                return k
        return None

    def _enforce_quota_and_touch(api_key_row, successful_call=True):
        # Returns None on ok, or error object
        if not isinstance(api_key_row, dict):
            return _err("UNAUTHORIZED", "Invalid API key.")
        if api_key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active.", status=api_key_row.get("status"))
        now = _now()
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, k in enumerate(keys):
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "API key not found.")
        row = keys[idx]

        # reset daily window if needed
        started = _parse_dt_lenient(row.get("daily_window_started_at"))
        if started is None:
            started = now
            row["daily_window_started_at"] = _iso(now)
            row["daily_used_requests"] = int(row.get("daily_used_requests") or 0)
        if (now - started) >= datetime.timedelta(hours=24):
            row["daily_used_requests"] = 0
            row["daily_window_started_at"] = _iso(now)

        limit = row.get("daily_limit_requests")
        used = row.get("daily_used_requests")
        try:
            limit_i = int(limit)
            used_i = int(used)
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if limit_i < 0 or used_i < 0:
            return _err("VALIDATION_ERROR", "API key quota fields must be non-negative.")
        # Enforce quota only for successful calls per business rules.
        if successful_call:
            if used_i + 1 > limit_i:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_limit_requests=limit_i, daily_used_requests=used_i)
            row["daily_used_requests"] = used_i + 1
            row["last_used_at"] = _iso(now)
            row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    t0 = time.time()

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")
    if include_results is None:
        include_results = False
    if not isinstance(include_results, bool):
        return _err("VALIDATION_ERROR", "include_results must be a boolean.", field="include_results")
    if results_limit is None:
        results_limit = 100
    if not isinstance(results_limit, int):
        return _err("VALIDATION_ERROR", "results_limit must be an integer.", field="results_limit")
    if results_limit < 1 or results_limit > 100:
        return _err("VALIDATION_ERROR", "results_limit must be between 1 and 100 inclusive.", field="results_limit")

    # Resolve and authorize
    key_row = _resolve_api_key(api_key)
    if key_row is None:
        _log("get_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")
    quota_err = _enforce_quota_and_touch(key_row, successful_call=False)
    if quota_err:
        _log("get_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": quota_err["error"]["code"]})
        return quota_err

    queries = _load("title_search_queries.json")
    if not isinstance(queries, list):
        queries = []

    # Fetch by id; if not found, return NOT_FOUND (realistic for single-resource GET)
    query = None
    for q in queries:
        if isinstance(q, dict) and q.get("id") == id.strip():
            query = q
            break
    if query is None:
        _log("get_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Query not found.", id=id.strip())

    # Enforce ownership
    if query.get("api_key_id") != key_row.get("id"):
        _log("get_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Query does not belong to this API key.", id=id.strip())

    # Build response
    out_query = dict(query)

    results = None
    if include_results:
        res_rows = _load("title_query_results.json")
        if not isinstance(res_rows, list):
            res_rows = []
        filtered = [r for r in res_rows if isinstance(r, dict) and r.get("query_id") == query.get("id")]
        # order by rank ascending, stable
        def _rank(v):
            try:
                return int(v.get("rank"))
            except Exception:
                return 10**18
        filtered.sort(key=_rank)
        filtered = filtered[:results_limit]
        results = filtered

    # Count as successful call now (increments quota)
    quota_err2 = _enforce_quota_and_touch(key_row, successful_call=True)
    if quota_err2:
        _log("get_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": quota_err2["error"]["code"]})
        return quota_err2

    body = {"query": out_query}
    if include_results:
        body["results"] = results or []
        body["results_count"] = len(body["results"])

    _log("get_title_search_query", key_row.get("id"), "ok", (time.time() - t0) * 1000, {"include_results": include_results, "results_limit": results_limit})
    return body

def create_title_search_query(api_key, title, requested_limit=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.isoformat().replace("+00:00", "Z")
        return None

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1]).replace(tzinfo=datetime.timezone.utc)
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _norm_title(t):
        t = t.strip()
        t = " ".join(t.split())
        return t.lower()

    def _gen_id(prefix):
        return f"{prefix}_{uuid.uuid4().hex}"

    def _log(endpoint, api_key_id, status_s, latency_ms, meta=None):
        logs = _load("request_logs.json")
        row = {
            "id": _gen_id("req"),
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta or {},
        }
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key:
        _log("create_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string")
    if not isinstance(title, str):
        _log("create_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title must be a string")
    if requested_limit is None:
        requested_limit = 20
    if not isinstance(requested_limit, int) or requested_limit < 1 or requested_limit > 100:
        _log("create_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "requested_limit must be between 1 and 100")

    trimmed = title.strip()
    if len(trimmed) == 0:
        _log("create_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "title must be non-empty after trimming")

    api_keys = _load("api_keys.json")
    krow = None
    for k in api_keys:
        if k.get("id") == api_key:
            krow = k
            break
    if krow is None:
        _log("create_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key")
    if krow.get("status") != "active":
        _log("create_title_search_query", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "API key is not active")

    now = _now()
    win = _parse_dt(krow.get("daily_window_started_at"))
    if win is None or (now - win >= datetime.timedelta(hours=24)):
        krow["daily_used_requests"] = 0
        krow["daily_window_started_at"] = _iso(now)

    used = krow.get("daily_used_requests")
    lim = krow.get("daily_limit_requests")
    if not isinstance(used, int) or not isinstance(lim, int) or lim < 0 or used < 0:
        _log("create_title_search_query", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "VALIDATION_ERROR"})
        return _err("VALIDATION_ERROR", "API key quota fields invalid")
    if used + 1 > lim:
        _log("create_title_search_query", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "QUOTA_EXCEEDED"})
        return _err("QUOTA_EXCEEDED", "Daily request quota exceeded")

    queries = _load("title_search_queries.json")
    title_norm = _norm_title(title)

    # enforce uniqueness: unique(api_key_id, title_normalized, status) where status in ('queued','fetching')
    for q in queries:
        if q.get("api_key_id") == krow.get("id") and q.get("title_normalized") == title_norm and q.get("status") in ("queued", "fetching"):
            _log("create_title_search_query", krow.get("id"), "error", (time.time() - t0) * 1000, {"code": "CONFLICT"})
            return _err("CONFLICT", "A queued or fetching query for this title already exists", existing_query_id=q.get("id"))

    row = {
        "id": _gen_id("tsq"),
        "api_key_id": krow.get("id"),
        "title_raw": title,
        "title_normalized": title_norm,
        "status": "queued",
        "requested_limit": requested_limit,
        "upstream_url": None,
        "upstream_http_status": None,
        "upstream_etag": None,
        "upstream_last_modified": None,
        "error_code": None,
        "error_message": None,
        "fetched_at": None,
        "cache_expires_at": None,
        "created_at": _iso(now),
        "updated_at": _iso(now),
    }
    queries.append(row)
    _save("title_search_queries.json", queries)

    # increment successful call
    krow["daily_used_requests"] = used + 1
    krow["last_used_at"] = _iso(now)
    krow["updated_at"] = _iso(now)
    for i, kk in enumerate(api_keys):
        if kk.get("id") == krow.get("id"):
            api_keys[i] = krow
            break
    _save("api_keys.json", api_keys)

    _log("create_title_search_query", krow.get("id"), "ok", (time.time() - t0) * 1000, {"query_id": row["id"]})
    return {"data": row}

def update_title_search_query(api_key, id, status=None, requested_limit=None, upstream_url=None, upstream_http_status=None, upstream_etag=None, upstream_last_modified=None, error_code=None, error_message=None, fetched_at=None, cache_expires_at=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            dt = s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string (RFC 3339).", field=field)
        ss = s.strip()
        if not ss:
            return _err("VALIDATION_ERROR", f"{field} must be a valid RFC 3339 timestamp.", field=field)
        try:
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid RFC 3339 timestamp.", field=field)

    def _parse_dt_lenient(v):
        if v is None:
            return None
        if isinstance(v, datetime.datetime):
            return v if v.tzinfo else v.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(v, str):
            return None
        s = v.strip()
        if not s:
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _iso(dt):
        if dt is None:
            return None
        if isinstance(dt, str):
            return dt
        if isinstance(dt, datetime.datetime):
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")
        return None

    def _log(endpoint, api_key_id, status_s, latency_ms, meta=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        ts = _iso(_now())
        logs.append({
            "id": f"olmk_req_{int(time.time()*1000)}_{len(logs)+1}",
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_s,
            "latency_ms": int(latency_ms),
            "timestamp": ts,
            "meta": meta or {},
        })
        _save("request_logs.json", logs)

    def _resolve_api_key(api_key_value):
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            return None
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None
        v = api_key_value.strip()
        for k in keys:
            if not isinstance(k, dict):
                continue
            if k.get("id") == v or k.get("key_hash") == v:
                return k
        return None

    def _enforce_quota_and_touch(api_key_row, successful_call=True):
        if not isinstance(api_key_row, dict):
            return _err("UNAUTHORIZED", "Invalid API key.")
        if api_key_row.get("status") != "active":
            return _err("UNAUTHORIZED", "API key is not active.", status=api_key_row.get("status"))
        now = _now()
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        idx = None
        for i, k in enumerate(keys):
            if isinstance(k, dict) and k.get("id") == api_key_row.get("id"):
                idx = i
                break
        if idx is None:
            return _err("UNAUTHORIZED", "API key not found.")
        row = keys[idx]

        started = _parse_dt_lenient(row.get("daily_window_started_at"))
        if started is None:
            started = now
            row["daily_window_started_at"] = _iso(now)
            row["daily_used_requests"] = int(row.get("daily_used_requests") or 0)
        if (now - started) >= datetime.timedelta(hours=24):
            row["daily_used_requests"] = 0
            row["daily_window_started_at"] = _iso(now)

        try:
            limit_i = int(row.get("daily_limit_requests"))
            used_i = int(row.get("daily_used_requests"))
        except Exception:
            return _err("VALIDATION_ERROR", "API key quota fields are invalid.")
        if limit_i < 0 or used_i < 0:
            return _err("VALIDATION_ERROR", "API key quota fields must be non-negative.")
        if successful_call:
            if used_i + 1 > limit_i:
                return _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_limit_requests=limit_i, daily_used_requests=used_i)
            row["daily_used_requests"] = used_i + 1
            row["last_used_at"] = _iso(now)
            row["updated_at"] = _iso(now)

        keys[idx] = row
        _save("api_keys.json", keys)
        return None

    def _is_valid_transition(cur, nxt):
        transitions = {
            "queued": ["fetching", "failed"],
            "fetching": ["succeeded", "failed"],
            "succeeded": ["queued"],
            "failed": ["queued"],
        }
        return nxt in transitions.get(cur, [])

    t0 = time.time()

    # Validate required params
    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")
    if not isinstance(id, str) or not id.strip():
        return _err("VALIDATION_ERROR", "id must be a non-empty string.", field="id")

    # Validate optionals
    if status is not None:
        if not isinstance(status, str):
            return _err("VALIDATION_ERROR", "status must be a string.", field="status")
        if status not in ("queued", "fetching", "succeeded", "failed"):
            return _err("VALIDATION_ERROR", "status must be one of: queued, fetching, succeeded, failed.", field="status")
    if requested_limit is not None:
        if not isinstance(requested_limit, int):
            return _err("VALIDATION_ERROR", "requested_limit must be an integer.", field="requested_limit")
        if requested_limit < 1 or requested_limit > 100:
            return _err("VALIDATION_ERROR", "requested_limit must be between 1 and 100 inclusive.", field="requested_limit")
    if upstream_http_status is not None:
        if not isinstance(upstream_http_status, int):
            return _err("VALIDATION_ERROR", "upstream_http_status must be an integer.", field="upstream_http_status")
        if upstream_http_status < 100 or upstream_http_status > 599:
            return _err("VALIDATION_ERROR", "upstream_http_status must be between 100 and 599 inclusive.", field="upstream_http_status")
    if upstream_last_modified is not None and not isinstance(upstream_last_modified, str):
        return _err("VALIDATION_ERROR", "upstream_last_modified must be a string.", field="upstream_last_modified")
    if fetched_at is not None:
        parsed = _parse_rfc3339(fetched_at, "fetched_at")
        if isinstance(parsed, dict) and parsed.get("error"):
            return parsed
        fetched_at_dt = parsed
    else:
        fetched_at_dt = None
    if cache_expires_at is not None:
        parsed = _parse_rfc3339(cache_expires_at, "cache_expires_at")
        if isinstance(parsed, dict) and parsed.get("error"):
            return parsed
        cache_expires_at_dt = parsed
    else:
        cache_expires_at_dt = None
    if upstream_url is not None and not isinstance(upstream_url, str):
        return _err("VALIDATION_ERROR", "upstream_url must be a string.", field="upstream_url")
    if upstream_etag is not None and not isinstance(upstream_etag, str):
        return _err("VALIDATION_ERROR", "upstream_etag must be a string.", field="upstream_etag")
    if error_code is not None and not isinstance(error_code, str):
        return _err("VALIDATION_ERROR", "error_code must be a string.", field="error_code")
    if error_message is not None and not isinstance(error_message, str):
        return _err("VALIDATION_ERROR", "error_message must be a string.", field="error_message")

    # Resolve API key; do not assume id is a query id (audit showed callers may pass key id accidentally)
    key_row = _resolve_api_key(api_key)
    if key_row is None:
        _log("update_title_search_query", None, "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Invalid API key.")
    quota_err = _enforce_quota_and_touch(key_row, successful_call=False)
    if quota_err:
        _log("update_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": quota_err["error"]["code"]})
        return quota_err

    queries = _load("title_search_queries.json")
    if not isinstance(queries, list):
        queries = []

    # Locate query by id; if not found, attempt a realistic recovery:
    # Some clients accidentally pass their api_key id in the 'id' field.
    target = None
    target_idx = None
    wanted_id = id.strip()
    for i, q in enumerate(queries):
        if isinstance(q, dict) and q.get("id") == wanted_id:
            target = q
            target_idx = i
            break
    if target is None and wanted_id == key_row.get("id"):
        # pick the most recent query belonging to this api key (by updated_at/created_at), since caller clearly intended "my latest"
        candidates = []
        for i, q in enumerate(queries):
            if isinstance(q, dict) and q.get("api_key_id") == key_row.get("id"):
                candidates.append((i, q))
        if candidates:
            def _dt_key(row):
                dt = _parse_dt_lenient(row.get("updated_at")) or _parse_dt_lenient(row.get("created_at")) or datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc)
                return dt
            candidates.sort(key=lambda t: _dt_key(t[1]), reverse=True)
            target_idx, target = candidates[0]

    if target is None:
        _log("update_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": "NOT_FOUND"})
        return _err("NOT_FOUND", "Query not found.", id=wanted_id)

    # Ownership check
    if target.get("api_key_id") != key_row.get("id"):
        _log("update_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": "UNAUTHORIZED"})
        return _err("UNAUTHORIZED", "Query does not belong to this API key.", id=target.get("id"))

    # Apply updates
    mutated = False
    now = _now()

    # Lifecycle transition
    if status is not None and status != target.get("status"):
        cur = target.get("status")
        if not isinstance(cur, str) or cur not in ("queued", "fetching", "succeeded", "failed"):
            _log("update_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Current query status is invalid; cannot transition.", current_status=cur, new_status=status)
        if not _is_valid_transition(cur, status):
            _log("update_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": "INVALID_TRANSITION"})
            return _err("INVALID_TRANSITION", "Invalid lifecycle transition.", current_status=cur, new_status=status, allowed=_is_valid_transition(cur, status))
        target["status"] = status
        mutated = True

        # If moving to failed, error_code/message are expected but not strictly required by schema; keep what provided.
        # If moving away from failed, clear error fields unless caller set them.
        if status != "failed":
            if error_code is None:
                target["error_code"] = None
            if error_message is None:
                target["error_message"] = None

    # Mutable fields
    if requested_limit is not None and requested_limit != target.get("requested_limit"):
        target["requested_limit"] = requested_limit
        mutated = True
    if upstream_url is not None and upstream_url != target.get("upstream_url"):
        target["upstream_url"] = upstream_url
        mutated = True
    if upstream_http_status is not None and upstream_http_status != target.get("upstream_http_status"):
        target["upstream_http_status"] = upstream_http_status
        mutated = True
    if upstream_etag is not None and upstream_etag != target.get("upstream_etag"):
        target["upstream_etag"] = upstream_etag
        mutated = True
    if upstream_last_modified is not None and upstream_last_modified != target.get("upstream_last_modified"):
        target["upstream_last_modified"] = upstream_last_modified
        mutated = True
    if error_code is not None and error_code != target.get("error_code"):
        target["error_code"] = error_code
        mutated = True
    if error_message is not None and error_message != target.get("error_message"):
        target["error_message"] = error_message
        mutated = True
    if fetched_at is not None:
        iso = _iso(fetched_at_dt)
        if iso != target.get("fetched_at"):
            target["fetched_at"] = iso
            mutated = True
    if cache_expires_at is not None:
        iso = _iso(cache_expires_at_dt)
        if iso != target.get("cache_expires_at"):
            target["cache_expires_at"] = iso
            mutated = True

    if not mutated:
        # No success without effect: treat as conflict-free no-op? Real APIs vary, but contract requires NOT_FOUND only when matched no row.
        # Here row exists; return it without counting as "mutation"? We'll still treat as successful call and log ok.
        pass
    else:
        target["updated_at"] = _iso(now)
        queries[target_idx] = target
        _save("title_search_queries.json", queries)

    quota_err2 = _enforce_quota_and_touch(key_row, successful_call=True)
    if quota_err2:
        _log("update_title_search_query", key_row.get("id"), "error", (time.time() - t0) * 1000, {"code": quota_err2["error"]["code"]})
        return quota_err2

    _log("update_title_search_query", key_row.get("id"), "ok", (time.time() - t0) * 1000, {"query_id": target.get("id"), "mutated": bool(mutated)})
    return {"query": dict(target)}

def list_ol_works(api_key, status=None, ol_work_key=None, title_contains=None, last_seen_after=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, time, uuid, base64, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s, field):
        if s is None:
            return None
        if not isinstance(s, str):
            return _err("VALIDATION_ERROR", f"{field} must be a string (RFC 3339).", field=field)
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return _err("VALIDATION_ERROR", f"{field} must be a valid RFC 3339 timestamp.", field=field)

    def _hash_key(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _audit(endpoint, api_key_id, status_code, latency_ms, meta=None):
        meta = meta or {}
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _auth_and_quota(api_key_value):
        if not isinstance(api_key_value, str) or not api_key_value.strip():
            return None, _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")
        keys = _load("api_keys.json")
        if not isinstance(keys, list):
            keys = []
        hv = _hash_key(api_key_value.strip())
        krow = None
        for r in keys:
            if isinstance(r, dict) and (r.get("id") == api_key_value or r.get("key_hash") == hv):
                krow = r
                break
        if not krow:
            return None, _err("UNAUTHORIZED", "Unknown API key.")
        if krow.get("status") != "active":
            return krow, _err("UNAUTHORIZED", "API key is not active.", status=krow.get("status"))

        now = _now()
        dws = krow.get("daily_window_started_at")
        dws_dt = None
        if isinstance(dws, str):
            parsed = _parse_rfc3339(dws, "daily_window_started_at")
            if not (isinstance(parsed, dict) and "error" in parsed):
                dws_dt = parsed
        if isinstance(dws, datetime.datetime):
            dws_dt = dws

        if dws_dt is None or (now - dws_dt) >= datetime.timedelta(hours=24):
            krow["daily_used_requests"] = 0
            krow["daily_window_started_at"] = _iso(now)

        limitv = krow.get("daily_limit_requests")
        used = krow.get("daily_used_requests")
        if not isinstance(limitv, int) or limitv < 0:
            return krow, _err("UNAUTHORIZED", "API key misconfigured (daily_limit_requests).")
        if not isinstance(used, int) or used < 0:
            used = 0
            krow["daily_used_requests"] = 0
        if used + 1 > limitv:
            return krow, _err("QUOTA_EXCEEDED", "Daily request quota exceeded.", daily_limit_requests=limitv, daily_used_requests=used)
        return krow, None

    t0 = time.time()

    # Validate filters
    if status is not None and (not isinstance(status, str) or status not in ("active", "tombstoned")):
        krow, _ = _auth_and_quota(api_key)
        if krow:
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "status"})
        return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=["active", "tombstoned"])
    if ol_work_key is not None and not isinstance(ol_work_key, str):
        krow, _ = _auth_and_quota(api_key)
        if krow:
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "ol_work_key"})
        return _err("VALIDATION_ERROR", "ol_work_key must be a string.", field="ol_work_key")
    if title_contains is not None and not isinstance(title_contains, str):
        krow, _ = _auth_and_quota(api_key)
        if krow:
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "title_contains"})
        return _err("VALIDATION_ERROR", "title_contains must be a string.", field="title_contains")

    lsa_dt = None
    pr = _parse_rfc3339(last_seen_after, "last_seen_after") if last_seen_after is not None else None
    if isinstance(pr, dict) and "error" in pr:
        krow, _ = _auth_and_quota(api_key)
        if krow:
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "last_seen_after"})
        return pr
    if isinstance(pr, datetime.datetime):
        lsa_dt = pr

    if limit is None:
        limit = 25
    if not isinstance(limit, int) or limit < 1 or limit > 100:
        krow, _ = _auth_and_quota(api_key)
        if krow:
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "limit"})
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 100.", field="limit")

    # Auth + quota
    krow, aerr = _auth_and_quota(api_key)
    if aerr:
        if krow:
            _audit("list_ol_works", krow.get("id"), aerr["error"]["code"], (time.time() - t0) * 1000)
        return aerr

    # Decode cursor (opaque base64 json {"offset": int})
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor.strip():
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string if provided.", field="cursor")
        try:
            payload = base64.urlsafe_b64decode(cursor.encode("utf-8") + b"===")
            obj = json.loads(payload.decode("utf-8"))
            off = obj.get("offset", 0)
            if not isinstance(off, int) or off < 0:
                raise ValueError("bad offset")
            offset = off
        except Exception:
            _audit("list_ol_works", krow.get("id"), "VALIDATION_ERROR", (time.time() - t0) * 1000, {"field": "cursor"})
            return _err("VALIDATION_ERROR", "Invalid cursor.", field="cursor")

    works = _load("ol_works.json")
    if not isinstance(works, list):
        works = []

    def _parse_dt_maybe(v):
        if isinstance(v, str):
            parsed = _parse_rfc3339(v, "last_seen_at")
            if isinstance(parsed, datetime.datetime):
                return parsed
        if isinstance(v, datetime.datetime):
            return v
        return None

    tc = title_contains.lower() if isinstance(title_contains, str) else None

    filtered = []
    for w in works:
        if not isinstance(w, dict):
            continue
        if status is not None and w.get("status") != status:
            continue
        if ol_work_key is not None and w.get("ol_work_key") != ol_work_key:
            continue
        if tc is not None:
            t = w.get("title")
            if not isinstance(t, str) or tc not in t.lower():
                continue
        if lsa_dt is not None:
            dt = _parse_dt_maybe(w.get("last_seen_at"))
            if dt is None or dt < lsa_dt:
                continue
        filtered.append(w)

    # Sort by last_seen_at desc, then id asc for stable pagination
    def _sort_key(w):
        dt = _parse_dt_maybe(w.get("last_seen_at"))
        # None last_seen_at goes last
        ts = dt.timestamp() if dt else -1e30
        return (-ts, str(w.get("id") or ""))

    filtered.sort(key=_sort_key)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(json.dumps({"offset": next_offset}).encode("utf-8")).decode("utf-8").rstrip("=")

    # Count successful tool call towards quota
    now = _now()
    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []
    for rr in keys:
        if isinstance(rr, dict) and rr.get("id") == krow.get("id"):
            rr["daily_used_requests"] = int(rr.get("daily_used_requests") or 0) + 1
            rr["last_used_at"] = _iso(now)
            rr["updated_at"] = _iso(now)
            break
    _save("api_keys.json", keys)

    _audit("list_ol_works", krow.get("id"), "OK", (time.time() - t0) * 1000, {"returned": len(page), "total": total})

    return {
        "works": page,
        "meta": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

def get_whoami(api_key, **_extra):
    import json, os, datetime, time, uuid, hashlib

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0333000" if __import__("os").path.isdir("./environment_mix/0333000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: 
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.now(datetime.timezone.utc)

    def _iso(dt):
        return dt.astimezone(datetime.timezone.utc).isoformat().replace("+00:00", "Z")

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            ss = s.strip()
            if ss.endswith("Z"):
                ss = ss[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(ss)
            if dt.tzinfo is None:
                dt = dt.replace(tzinfo=datetime.timezone.utc)
            return dt.astimezone(datetime.timezone.utc)
        except Exception:
            return None

    def _hash_key(k):
        return hashlib.sha256(k.encode("utf-8")).hexdigest()

    def _audit(endpoint, api_key_id, status_code, latency_ms, meta=None):
        meta = meta or {}
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "status": status_code,
            "latency_ms": int(latency_ms),
            "timestamp": _iso(_now()),
            "meta": meta
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    t0 = time.time()

    if not isinstance(api_key, str) or not api_key.strip():
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")

    keys = _load("api_keys.json")
    if not isinstance(keys, list):
        keys = []

    hv = _hash_key(api_key.strip())
    krow = None
    for r in keys:
        if isinstance(r, dict) and (r.get("id") == api_key or r.get("key_hash") == hv):
            krow = r
            break

    if not krow:
        # Can't attribute audit to a key id; record as unknown
        _audit("get_whoami", None, "UNAUTHORIZED", (time.time() - t0) * 1000)
        return _err("UNAUTHORIZED", "Unknown API key.")

    now = _now()
    dws_dt = _parse_rfc3339(krow.get("daily_window_started_at")) if isinstance(krow.get("daily_window_started_at"), str) else None
    if dws_dt is None:
        dws_dt = now
    if (now - dws_dt) >= datetime.timedelta(hours=24):
        # reset window on introspection too (doesn't count as usage increment)
        krow["daily_used_requests"] = 0
        krow["daily_window_started_at"] = _iso(now)
        krow["updated_at"] = _iso(now)
        # persist key update
        for rr in keys:
            if isinstance(rr, dict) and rr.get("id") == krow.get("id"):
                rr.update(krow)
                break
        _save("api_keys.json", keys)

    resp = {
        "api_key": {
            "id": krow.get("id"),
            "label": krow.get("label"),
            "status": krow.get("status"),
            "created_at": krow.get("created_at"),
            "updated_at": krow.get("updated_at"),
            "last_used_at": krow.get("last_used_at"),
        },
        "quota": {
            "daily_limit_requests": krow.get("daily_limit_requests"),
            "daily_used_requests": krow.get("daily_used_requests"),
            "daily_window_started_at": krow.get("daily_window_started_at"),
            "daily_window_ends_at": _iso(dws_dt + datetime.timedelta(hours=24)),
            "is_active": (krow.get("status") == "active"),
            "remaining_requests": None
        },
        "scopes": []
    }

    try:
        lim = krow.get("daily_limit_requests")
        used = krow.get("daily_used_requests")
        if isinstance(lim, int) and lim >= 0 and isinstance(used, int) and used >= 0:
            resp["quota"]["remaining_requests"] = max(lim - used, 0)
    except Exception:
        pass

    _audit("get_whoami", krow.get("id"), "OK", (time.time() - t0) * 1000)

    return resp
